const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const signatureHeader = headers['x-lit-signature'] || headers['X-LIT-Signature'] || '';
const timestampHeader = headers['x-lit-timestamp'] || headers['X-LIT-Timestamp'] || '';
const eventIdHeader = headers['x-lit-event-id'] || headers['X-LIT-Event-ID'] || '';
const rawBody = $input.first().json.rawBody || JSON.stringify($input.first().json.body || {});

if (!signatureHeader || !timestampHeader || !eventIdHeader) {
  throw new Error('HMAC verification failed: Missing required LIT security headers (X-LIT-Signature, X-LIT-Timestamp, X-LIT-Event-ID)');
}

const now = Math.floor(Date.now() / 1000);
const timestamp = parseInt(timestampHeader, 10);
if (isNaN(timestamp) || Math.abs(now - timestamp) > 300) {
  throw new Error(`HMAC verification failed: Timestamp tolerance exceeded (diff: ${Math.abs(now - timestamp)}s > 300s)`);
}

const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret || typeof secret !== 'string' || secret.trim().length === 0) {
  throw new Error('HMAC verification failed: N8N_WEBHOOK_SECRET environment variable is missing or empty (fail-closed)');
}

const expectedSignature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${eventIdHeader}.${rawBody}`)
  .digest('hex');

const sigBuffer = Buffer.from(signatureHeader);
const expBuffer = Buffer.from(expectedSignature);
if (sigBuffer.length !== expBuffer.length || !crypto.timingSafeEqual(sigBuffer, expBuffer)) {
  throw new Error('HMAC verification failed: Invalid cryptographic signature');
}

const body = typeof $input.first().json.body === 'object' ? $input.first().json.body : JSON.parse(rawBody);

return [{
  json: {
    verified: true,
    event_id: eventIdHeader,
    timestamp: timestamp,
    payload: body
  }
}];

// Zero-Raw-Audio, Zero-Biometric-Embedding, Zero-PHI Boundary Assertion
const PROHIBITED_KEYS = [
  'raw_audio', 'audio_chunk', 'pcm_data', 'voiceprint', 'biometric_embedding',
  'spectrogram', 'waveform', 'phone_number', 'patient', 'clinical_notes',
  'mrn', 'ssn', 'aadhaar', 'auth_token', 'password_hash'
];

function sanitizeCheck(obj, path = '') {
  if (!obj || typeof obj !== 'object') return;
  for (const [k, v] of Object.entries(obj)) {
    const currentPath = path ? `${path}.${k}` : k;
    if (PROHIBITED_KEYS.includes(k.toLowerCase())) {
      throw new Error(`Zero-Biometric/PHI Boundary Violation: Prohibited field detected at ${currentPath}`);
    }
    if (typeof v === 'object') sanitizeCheck(v, currentPath);
  }
}

const payload = $input.first().json.payload;
sanitizeCheck(payload);

return [{
  json: {
    ...$input.first().json,
    sanitized: true
  }
}];
